/**
 * Keeping credentials out of error alerts.
 *
 * Alerts are stored and mailed, and their text is whatever the failing code
 * said - a failed fetch, for instance, lists the URLs it tried. The case that
 * prompted this is the first one below, word for word: the disclosure briefing
 * failed in production and the alert carried the OpenDART key.
 */
import { describe, expect, it } from 'vitest'
import { redactSecrets } from '../http/pipeline.js'

describe('redactSecrets', () => {
  it('실제로 새었던 메시지에서 키를 지운다', () => {
    const leaked =
      'Too many redirects.https://opendart.fss.or.kr/api/list.json?crtfc_key=cb713040e460e61aecb05b71c8852480613a5a9a&bgn_de=20261003, https://opendart.fss.or.kr/error1.html'
    const clean = redactSecrets(leaked)
    expect(clean).not.toContain('cb713040e460e61aecb05b71c8852480613a5a9a')
    expect(clean).toContain('crtfc_key=[숨김]')
    // What is useful for diagnosis stays.
    expect(clean).toContain('bgn_de=20261003')
    expect(clean).toContain('error1.html')
  })

  it('흔한 자격 증명 파라미터를 지운다', () => {
    for (const name of ['api_key', 'apikey', 'key', 'token', 'access_token', 'client_secret', 'password', 'sig']) {
      const clean = redactSecrets(`https://x.example/a?${name}=SECRET123456&page=2`)
      expect(clean).not.toContain('SECRET123456')
      expect(clean).toContain('page=2')
    }
  })

  it('Bearer 토큰과 이 서비스의 키 형식을 지운다', () => {
    expect(redactSecrets('Authorization: Bearer abcdefghijklmnop')).not.toContain('abcdefghijklmnop')
    for (const secret of ['re_uu2i662C_3EVejEwRMi8t34', 'sb_secret_4GKdUG48MviNnxdF31', 'cfat_lJC7Hp6JkuIGatxp']) {
      expect(redactSecrets(`failed with ${secret} here`)).not.toContain(secret.slice(-10))
    }
  })

  it('연결 문자열의 비밀번호를 지운다', () => {
    const clean = redactSecrets('connect postgres://yeopjari_app.ref:p4ssw0rd-x@pooler.example:6543/postgres failed')
    expect(clean).not.toContain('p4ssw0rd-x')
    expect(clean).toContain('pooler.example:6543')
  })

  it('비밀이 없는 메시지는 그대로 둔다', () => {
    const plain = 'write CONNECTION_CLOSED 6cfab0796881f69dcb222fef1c6d9f25.hyperdrive.local:5432'
    expect(redactSecrets(plain)).toBe(plain)
  })
})
import { describe, expect, it } from 'vitest'
import { pickCampaign } from '../components/AdSlot'
import type { AdCampaign, AdsConfig } from '../api/types'

const campaign = (id: string, extra: Partial<AdCampaign> = {}): AdCampaign => ({
  id,
  kind: 'house',
  sponsor: '',
  title: id,
  body: '',
  cta: '자세히',
  link: '/',
  placements: ['feed', 'companies'],
  sector: '',
  area_id: null,
  weight: 10,
  ...extra,
})

const ads = (campaigns: AdCampaign[]): AdsConfig => ({ feed_after: 8, campaigns, google: null })

describe('pickCampaign', () => {
  it('keeps to the placement and skips what the reader hid', () => {
    const config = ads([campaign('a', { placements: ['market'] }), campaign('b'), campaign('c')])
    expect(pickCampaign(config, 'market', {}, {}, 0.5)?.id).toBe('a')
    expect(pickCampaign(config, 'market', {}, { a: Date.now() + 1000 }, 0.5)).toBeNull()
    expect(pickCampaign(config, 'feed', {}, { b: Date.now() + 1000 }, 0)?.id).toBe('c')
  })

  it('shows an aimed campaign only on its own sector or area, ahead of general ones', () => {
    const config = ads([campaign('general'), campaign('it', { sector: 'IT', weight: 1 }), campaign('seongsu', { area_id: 'x' })])
    expect(pickCampaign(config, 'feed', { sector: 'IT' }, {}, 0.99)?.id).toBe('it')
    expect(pickCampaign(config, 'feed', { sector: '제조' }, {}, 0.99)?.id).toBe('general')
    expect(pickCampaign(config, 'feed', { areaId: 'x' }, {}, 0.99)?.id).toBe('seongsu')
  })

  it('splits by weight', () => {
    const config = ads([campaign('heavy', { weight: 90 }), campaign('light', { weight: 10 })])
    expect(pickCampaign(config, 'feed', {}, {}, 0.5)?.id).toBe('heavy')
    expect(pickCampaign(config, 'feed', {}, {}, 0.95)?.id).toBe('light')
  })
})
import { beforeEach, describe, expect, it } from 'vitest'
import { invalidateAll, peek, remember } from '../api/cache'

describe('read cache', () => {
  beforeEach(() => invalidateAll())

  it('answers from memory within the age, and asks again after it', async () => {
    let calls = 0
    const load = async () => ++calls
    expect(await remember('a', 1_000, load)).toBe(1)
    expect(await remember('a', 1_000, load)).toBe(1)
    expect(await remember('a', -1, load)).toBe(2)
  })

  it('merges identical reads in flight into one request', async () => {
    let calls = 0
    const load = () => new Promise<number>((resolve) => setTimeout(() => resolve(++calls), 5))
    const [x, y] = await Promise.all([remember('b', 1_000, load), remember('b', 1_000, load)])
    expect([x, y, calls]).toEqual([1, 1, 1])
  })

  it('forgets failures so a retry really retries', async () => {
    let calls = 0
    const failing = async () => {
      calls++
      throw new Error('down')
    }
    await expect(remember('c', 1_000, failing)).rejects.toThrow('down')
    await expect(remember('c', 1_000, failing)).rejects.toThrow('down')
    expect(calls).toBe(2)
  })

  it('a write empties everything', async () => {
    await remember('d', 60_000, async () => 'old')
    invalidateAll()
    expect(peek('d', 60_000)).toBeUndefined()
    expect(await remember('d', 60_000, async () => 'new')).toBe('new')
  })

  it('does not keep an answer that was on the wire when a write happened', async () => {
    let release: (value: string) => void = () => {}
    const pending = remember('e', 60_000, () => new Promise<string>((resolve) => (release = resolve)))
    invalidateAll() // the reader saved something meanwhile
    release('from before the write')
    expect(await pending).toBe('from before the write')
    // ...but it is not served to the next reader as if it were current.
    expect(peek('e', 60_000)).toBeUndefined()
  })
})
/**
 * Lint rules that exist because something shipped.
 *
 * The repository went a long time without a linter, and the bug that finally
 * justified one was a whole class rather than a single mistake: thirteen change
 * handlers across two files read event.currentTarget inside a setState updater.
 * Fixing the instances by hand does nothing about the fourteenth, so the class
 * is a rule now.
 */
import js from '@eslint/js'
import tseslint from 'typescript-eslint'
import reactHooks from 'eslint-plugin-react-hooks'

/**
 * Bans reading a React event inside a state updater callback.
 *
 *   setDraft((d) => ({ ...d, industry: e.currentTarget.value }))  // throws
 *   setQuery(e.currentTarget.value)                               // fine
 *
 * The updater does not run while the handler does. React defers it to the next
 * render once an update is already pending, and by then currentTarget is null -
 * so the form dies on the second keystroke while surviving every test that
 * types a single character.
 *
 * Only functions passed to a setter are examined, so reading the event in the
 * handler itself - the correct thing to do - is left alone.
 */
const noEventInStateUpdater = {
  meta: {
    type: 'problem',
    docs: { description: 'React 이벤트를 setState updater 안에서 읽지 않는다' },
    schema: [],
    messages: {
      deferred:
        'setState updater 안에서 {{prop}} 를 읽습니다. updater 는 렌더 중에 실행되고 그때 이 값은 null 입니다. ' +
        '핸들러 안에서 값을 먼저 꺼내 updater 에는 값만 넘기세요 (apps/web/src/state/fieldSetter.ts).',
    },
  },
  create(context) {
    const BANNED = new Set(['currentTarget', 'nativeEvent'])
    // Depth of nested functions that are arguments to a `setX(...)` call.
    const updaters = []

    function isUpdaterArgument(node) {
      const parent = node.parent
      if (!parent || parent.type !== 'CallExpression') return false
      if (!parent.arguments.includes(node)) return false
      const callee = parent.callee
      const name =
        callee.type === 'Identifier'
          ? callee.name
          : callee.type === 'MemberExpression' && callee.property.type === 'Identifier'
            ? callee.property.name
            : ''
      return /^set[A-Z]/.test(name)
    }

    const enter = (node) => {
      if (isUpdaterArgument(node)) updaters.push(node)
    }
    const exit = (node) => {
      if (updaters[updaters.length - 1] === node) updaters.pop()
    }

    return {
      ArrowFunctionExpression: enter,
      'ArrowFunctionExpression:exit': exit,
      FunctionExpression: enter,
      'FunctionExpression:exit': exit,
      MemberExpression(node) {
        if (updaters.length === 0) return
        if (node.property.type !== 'Identifier' || !BANNED.has(node.property.name)) return
        context.report({ node, messageId: 'deferred', data: { prop: node.property.name } })
      },
    }
  },
}

